// Converts the oklch() colours of the web app's stylesheets into sRGB and writes
// lib/theme/tokens.g.dart. Run from `app/`:  node tool/gen_tokens.mjs
//
// The CSS is the source of truth (web/src/app.css, web/src/lib/console.css); never edit the
// generated file by hand. Also prints the WCAG contrast of the text pairs the app uses, and exits
// non-zero when one falls below AA.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const appCss = readFileSync(resolve(here, '../../web/src/app.css'), 'utf8');
const consoleCss = readFileSync(resolve(here, '../../web/src/lib/console.css'), 'utf8');

// ---------------------------------------------------------------- oklch -> sRGB

function oklchToSrgb(l, c, hDeg) {
	const h = (hDeg * Math.PI) / 180;
	const a = c * Math.cos(h);
	const b = c * Math.sin(h);
	const l_ = (l + 0.3963377774 * a + 0.2158037573 * b) ** 3;
	const m_ = (l - 0.1055613458 * a - 0.0638541728 * b) ** 3;
	const s_ = (l - 0.0894841775 * a - 1.291485548 * b) ** 3;
	const linear = [
		4.0767416621 * l_ - 3.3077115913 * m_ + 0.2309699292 * s_,
		-1.2684380046 * l_ + 2.6097574011 * m_ - 0.3413193965 * s_,
		-0.0041960863 * l_ - 0.7034186147 * m_ + 1.707614701 * s_
	];
	return linear.map((v) => {
		const clamped = Math.min(1, Math.max(0, v));
		const encoded = clamped <= 0.0031308 ? 12.92 * clamped : 1.055 * clamped ** (1 / 2.4) - 0.055;
		return Math.round(encoded * 255);
	});
}

function parseOklch(text) {
	const match = /oklch\(\s*([\d.]+)%\s+([\d.]+)\s+([\d.]+)\s*\)/.exec(text);
	if (!match) throw new Error(`Not a plain oklch() colour: ${text}`);
	return oklchToSrgb(Number(match[1]) / 100, Number(match[2]), Number(match[3]));
}

const hex = (rgb) => rgb.map((v) => v.toString(16).padStart(2, '0')).join('').toUpperCase();

function luminance([r, g, b]) {
	const lin = (v) => {
		const s = v / 255;
		return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
	};
	return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
}

function contrast(a, b) {
	const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x);
	return (hi + 0.05) / (lo + 0.05);
}

// ---------------------------------------------------------------- read the CSS

/** `--color-name: oklch(...)` declarations inside the first block that starts with `opener`. */
function colours(css, opener, prefix = '--color-') {
	const start = css.indexOf(opener);
	if (start < 0) throw new Error(`Block not found: ${opener}`);
	const end = css.indexOf('\n\t}', start) > 0 && opener.startsWith('.light')
		? css.indexOf('\n\t}', start)
		: css.indexOf('\n}', start);
	const block = css.slice(start, end);
	const out = {};
	for (const m of block.matchAll(new RegExp(`${prefix}([a-z0-9-]+):\\s*(oklch\\([^)]*\\))`, 'g'))) {
		out[m[1]] = parseOklch(m[2]);
	}
	return out;
}

const camel = (name) => name.replace(/-([a-z0-9])/g, (_, ch) => ch.toUpperCase());

const dark = colours(appCss, '@theme {');
const sheetOverrides = colours(appCss, '.light,\n\tdialog.sheet {');
const sheet = { ...dark, ...sheetOverrides };

const lampBlock = (name) => {
	const m = new RegExp(`\\.lamp-${name}\\s*\\{\\s*--lamp:\\s*(oklch\\([^)]*\\))`).exec(consoleCss);
	if (!m) throw new Error(`Lamp not found: ${name}`);
	return parseOklch(m[1]);
};
const tagText = (() => {
	const m = /\.tag-signal\s*\{[^}]*?\bcolor:\s*(oklch\([^)]*\))/.exec(consoleCss);
	if (!m) throw new Error('.tag-signal colour not found');
	return parseOklch(m[1]);
})();
const lamps = { green: lampBlock('green'), amber: lampBlock('amber'), blue: lampBlock('blue'), red: lampBlock('red') };

// `void` is a reserved word in Dart.
const dartName = (name) => (name === 'void' ? 'voidSurface' : camel(name));

// What the app uses; the web names are kept (see the brief, section 3).
const NAMES = [
	'backing', 'void', 'paper', 'paper-2', 'ink', 'gray-200', 'gray-300', 'gray-400', 'gray-600',
	'brand', 'brand-hover', 'brand-text', 'green-700', 'green-500', 'red-400', 'red-500',
	'yellow-500', 'blue-500'
];

function palette(source, label) {
	const lines = NAMES.map((n) => {
		if (!source[n]) throw new Error(`${label}: token ${n} missing`);
		return `  final Color ${dartName(n)};`;
	});
	return lines.join('\n');
}

const ctor = (source) =>
	NAMES.map((n) => `    ${dartName(n)}: Color(0xFF${hex(source[n])}),`).join('\n');

const out = `// GENERATED by tool/gen_tokens.mjs from web/src/app.css and web/src/lib/console.css.
// Do not edit by hand; change the CSS and run \`node tool/gen_tokens.mjs\`.
import 'dart:ui';

/// One set of the web app's colour tokens. \`voidSurface\` is the CSS \`--color-void\`
/// (\`void\` is a reserved word in Dart).
class Palette {
  const Palette({
${NAMES.map((n) => `    required this.${dartName(n)},`).join('\n')}
  });

${palette(dark, 'dark')}

  /// The dark app (\`@theme\`).
  static const dark = Palette(
${ctor(dark)}
  );

  /// The inverted light surface (\`.light, dialog.sheet\`).
  static const sheet = Palette(
${ctor(sheet)}
  );
}

/// Status lamp colours (\`.lamp-*\` in console.css).
class LampColors {
  const LampColors._();
${Object.entries(lamps).map(([k, v]) => `  static const Color ${k} = Color(0xFF${hex(v)});`).join('\n')}

  /// The text of the \`VIRTUAL\` tag (\`.tag-signal\`).
  static const Color tagText = Color(0xFF${hex(tagText)});
}
`;

writeFileSync(resolve(here, '../lib/theme/tokens.g.dart'), out);

// The same colours for the iOS Live Activity (SwiftUI).
const swiftColor = (rgb) =>
	`Color(red: ${(rgb[0] / 255).toFixed(4)}, green: ${(rgb[1] / 255).toFixed(4)}, blue: ${(rgb[2] / 255).toFixed(4)})`;
const swiftNames = ['backing', 'void', 'paper', 'paper-2', 'ink', 'gray-200', 'gray-300', 'gray-400', 'gray-600', 'brand', 'brand-hover', 'brand-text'];
const swift = `// GENERATED by app/tool/gen_tokens.mjs from web/src/app.css. Do not edit by hand.
import SwiftUI

enum Tokens {
${swiftNames.map((n) => `    static let ${n === 'void' ? 'voidSurface' : camel(n)} = ${swiftColor(dark[n])}`).join('\n')}
    static let lampGreen = ${swiftColor(lamps.green)}
    static let tagText = ${swiftColor(tagText)}
}
`;
writeFileSync(resolve(here, '../ios/DoorActivity/Tokens.g.swift'), swift);

// ---------------------------------------------------------------- contrast report

// On the light sheet the web's brand-text, green-700 and red-500 are below 4.5:1 against its `void`
// (4.46, 4.27, 3.67), so the app never sets text in them there: the sheet's text is ink or gray,
// and state is carried by a lamp.
const pairs = [
	['dark ink on void', dark.ink, dark.void],
	['dark ink on paper', dark.ink, dark.paper],
	['dark gray600 on paper2', dark['gray-600'], dark['paper-2']],
	['dark gray400 on void', dark['gray-400'], dark.void],
	['dark gray400 on paper', dark['gray-400'], dark.paper],
	['dark gray400 on backing', dark['gray-400'], dark.backing],
	['dark brandText on void', dark['brand-text'], dark.void],
	['dark brandText on paper', dark['brand-text'], dark.paper],
	['white on brand', [255, 255, 255], dark.brand],
	['white on brandHover', [255, 255, 255], dark['brand-hover']],
	['dark red500 on paper', dark['red-500'], dark.paper],
	['dark red400 on void', dark['red-400'], dark.void],
	['dark green700 on paper', dark['green-700'], dark.paper],
	['sheet ink on void', sheet.ink, sheet.void],
	['sheet gray400 on void', sheet['gray-400'], sheet.void],
	['sheet gray600 on paper2', sheet['gray-600'], sheet['paper-2']],
	['white on brand (sheet primary)', [255, 255, 255], sheet.brand]
];
let failed = false;
for (const [label, fg, bg] of pairs) {
	const ratio = contrast(fg, bg);
	const ok = ratio >= 4.5;
	if (!ok) failed = true;
	console.log(`${ok ? 'ok  ' : 'FAIL'} ${ratio.toFixed(2).padStart(5)}  ${label}`);
}
if (failed) {
	console.error('\nSome text pairs are below WCAG AA (4.5:1).');
	process.exitCode = 1;
}
